// pale-periwinkle wash + frosted glass (generated by tooling/skin/apply.py; do not edit)
import SwiftUI

/// Rounded glass for the Bot and group rows, using the native material on iOS 26.
struct BotRowGlass: View {
    let isSelected: Bool

    var body: some View {
        surface
            .padding(.horizontal, 10)
            .padding(.vertical, 3)
    }

    @ViewBuilder
    private var surface: some View {
        let shape = RoundedRectangle(cornerRadius: 22, style: .continuous)
        if #available(iOS 26.0, *) {
            Color.clear.glassEffect(isSelected ? .regular.tint(Palette.bubble) : .regular, in: shape)
        } else {
            shape.fill(.ultraThinMaterial)
                .overlay(shape.fill(isSelected ? Palette.bubble.opacity(0.65) : Color.clear))
        }
    }
}
